fc-gather:
const n=22,e=U.ease(t/0.85)
for(let i=0;i<n;i++){const a=i*U.TAU/n+rng.uniform(-0.15,0.15)+1.2*e, d=U.C*0.42*(1-0.88*e)*rng.uniform(0.85,1.1), b=a-0.25*(1-e), q=d+10*(1-e)
 pen.stroke([[q*Math.cos(b),q*Math.sin(b)],[d*Math.cos(a),d*Math.sin(a)]],0.3,1.4+1.2*e,0.5+0.5*e)}
pen.dot(0,0,2+8*e,0.4+0.6*e)
return {motes:false}

fc-trail:
const hy=35, top=-70
for(let j=-2;j<=2;j++){const x0=j*3.2, L=(1-Math.abs(j)*0.22)*(hy-top); pen.stroke(U.linspace(0,1,16).map(f=>[x0*(1+1.6*f)+Math.sin(f*9+t*U.TAU*2+j)*0.8*f,hy-L*f]),j?1.1:2.6,0.25,j?0.7:1)}
for(let i=0;i<8;i++){const f=(i/8+t*2)%1; pen.dot(rng.uniform(-9,9)*f,hy-(hy-top)*f,1.6*(1-f)+0.3,0.85)}
pen.dot(0,hy,8,1)
return {motes:false}

fc-shock:
const R=U.C*0.45
const ring=(tt,rs,w)=>{if(tt<0)return 0;const r=rs*(0.3+0.7*U.ease(tt/0.5)),th=w*(1-U.ease(tt/0.75))+0.4;pen.stroke(U.arc(r,0,U.TAU,{k:80}),th,th,1);return r}
const r=ring(t,R,2.6); ring(t-0.08,R*0.75,1.3)
for(let i=0;i<16;i++){const a=i*U.TAU/16+rng.uniform(-0.1,0.1);pen.stroke([[r*Math.cos(a),r*Math.sin(a)],[(r+6)*Math.cos(a),(r+6)*Math.sin(a)]],1.4*(1-t)+0.3,0.3,0.9)}

fc-glitter:
const R=U.C*0.42
for(let i=0;i<18;i++){const a=-U.PI/2+rng.uniform(-1.3,1.3), sp=R*rng.uniform(0.7,1.25)
 const P=tt=>[Math.cos(a)*sp*tt,Math.sin(a)*sp*tt+R*1.5*tt*tt]
 pen.stroke(U.linspace(Math.max(0,t-0.07),t,5).map(P),0.25,1.3,1)}

fc-cracks:
const R=U.C*0.4; for(let i=0;i<7;i++){const a=i*U.TAU/7+rng.uniform(-0.25,0.25), r0=22, L=r0+(R*rng.uniform(0.75,1.05)-r0)*U.ease((t-0.05)/0.45)
 if(L>r0+0.5){pen.stroke(U.jag(rng,r0*Math.cos(a),r0*Math.sin(a),L*Math.cos(a),L*Math.sin(a),5,3),1.2,0.25,0.9)
  const m=r0+(L-r0)*0.5,b=a+rng.uniform(-0.8,0.8),l=(L-r0)*0.4; pen.stroke(U.jag(rng,m*Math.cos(a),m*Math.sin(a),m*Math.cos(a)+l*Math.cos(b),m*Math.sin(a)+l*Math.sin(b),3,2),0.8,0.2,0.75)}}
